        "code": "import { EquipmentStatusCard } from \"@/components/blocks/openlmis/equipment-status\"\n\nexport default function Page() {\n  return (\n    <div className=\"w-full max-w-sm p-8\">\n      <EquipmentStatusCard\n        counts={{\n          FUNCTIONING: 42,\n          NEEDS_ATTENTION: 6,\n          AWAITING_REPAIR: 3,\n          UNSERVICEABLE: 2,\n        }}\n      />\n    </div>\n  )\n}",
